"use strict";(self.webpackChunktmrw_help=self.webpackChunktmrw_help||[]).push([["9500"],{48553(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>c});var a=JSON.parse('{"id":"Navigating/fo-overview","title":"Finance and Operations \u2013 User Guide","description":"About the Platform","source":"@site/../help/finops/01-Navigating/overview.md","sourceDirName":"01-Navigating","slug":"/Navigating/fo-overview","permalink":"/fo/Navigating/fo-overview","draft":false,"unlisted":false,"editUrl":"https://github.com/tmrw-education/help/edit/main/../help/finops/01-Navigating/overview.md","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"id":"fo-overview","summary":["F&O is the financial backbone of the tmrw platform, built on Microsoft Dynamics 365 Finance & Operations.","Because F&O shares a unified data layer with Student Management and HR, fee generation, payments, and reporting flow through one source of truth.","This guide covers fees, payments, scholarships, discounts, and related financial processes for finance staff and bursars."],"keywords":["F&O overview","finance and operations","what is FNO","tmrw finance","Dynamics 365 finance","platform overview"],"video":{"youtube":null,"bunny":null}},"sidebar":"autogenerated","previous":{"title":"Navigating F&O","permalink":"/fo/Navigating/"},"next":{"title":"Basic Navigation in F&O","permalink":"/fo/Navigating/navigate-the-platform"}}'),i=t(74848),o=t(28453);let s={sidebar_position:1,id:"fo-overview",summary:["F&O is the financial backbone of the tmrw platform, built on Microsoft Dynamics 365 Finance & Operations.","Because F&O shares a unified data layer with Student Management and HR, fee generation, payments, and reporting flow through one source of truth.","This guide covers fees, payments, scholarships, discounts, and related financial processes for finance staff and bursars."],keywords:["F&O overview","finance and operations","what is FNO","tmrw finance","Dynamics 365 finance","platform overview"],video:{youtube:null,bunny:null}},r="Finance and Operations \u2013 User Guide",c={},l=[{value:"About the Platform",id:"about-the-platform",level:2},{value:"Where Finance and Operations Fits",id:"where-finance-and-operations-fits",level:2},{value:"How to Use This Guide",id:"how-to-use-this-guide",level:2}];function d(e){let n={h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"finance-and-operations--user-guide",children:"Finance and Operations \u2013 User Guide"})}),"\n",(0,i.jsx)(n.h2,{id:"about-the-platform",children:"About the Platform"}),"\n",(0,i.jsx)(n.p,{children:"Education's greatest challenge isn't a lack of technology \u2014 it's too much of it. Across most K\u201312 systems, finance teams work across a patchwork of tools that don't talk to each other: one platform for enrolment, another for fees, a third for general ledger, and a string of spreadsheets to reconcile what each one says. The result is duplicated effort, delayed reporting, and a finance function that spends more time stitching data together than acting on it."}),"\n",(0,i.jsx)(n.p,{children:"tmrw is built to change that. tmrw is an AI-first education intelligence platform, designed specifically for K\u201312 and developed in partnership with GEMS Education to ensure it is grounded in the operational reality of running schools at scale. Rather than bolting AI onto existing tools, tmrw embeds intelligence directly into the core of school operations, teaching, and learning \u2014 turning fragmented data into insight, and insight into action that improves outcomes for students, educators, leaders, and families."}),"\n",(0,i.jsx)(n.p,{children:"The platform unifies the essential systems a school or school group depends on \u2014 Finance, HR, Procurement, School and Student Management, and Teaching and Learning \u2014 onto a single Microsoft-based foundation built on Dynamics 365, Microsoft 365, Azure, Copilot, and Dataverse. On top of this foundation sit three Experience layers (Parent XP, Staff XP, and Learner XP) and a network of intelligent AI agents that automate workflows and connect processes that have historically lived in isolation. Attendance, wellbeing, enrolment, fee generation, payment processing, and reporting are no longer separate systems \u2014 they are part of one connected conversation."}),"\n",(0,i.jsx)(n.h2,{id:"where-finance-and-operations-fits",children:"Where Finance and Operations Fits"}),"\n",(0,i.jsx)(n.p,{children:"The Finance and Operations (F&O) module is the financial backbone of the tmrw platform, delivered through Microsoft Dynamics 365 Finance & Operations. Because F&O sits on the same unified data layer as Student Management, HR, and the Experience layers, financial transactions are no longer disconnected from the student and family records they relate to. When a student is enrolled, transferred, granted a scholarship, or charged for a sessional class, the financial impact flows through the same source of truth \u2014 eliminating the manual exports, re-keying, and end-of-month reconciliation that finance teams have come to accept as unavoidable."}),"\n",(0,i.jsx)(n.p,{children:"For finance staff, bursars, and operations teams, this means three practical shifts. Day-to-day fee generation, payment processing, scholarship approval, and statement production are streamlined into clearer end-to-end processes rather than spread across multiple disconnected tools. Real-time, accurate financial data is available to school leaders without waiting for batch reports or manual consolidation. And complex, error-prone tasks such as pro-rata adjustments, sibling discounts, split billing, and settlement discounts are handled by the platform's built-in logic, with audit trails maintained automatically."}),"\n",(0,i.jsx)(n.h2,{id:"how-to-use-this-guide",children:"How to Use This Guide"}),"\n",(0,i.jsx)(n.p,{children:"This guide provides step-by-step instructions for managing fees, payments, scholarships, discounts, and related financial processes in F&O. It is written for finance and operations staff who work in the system daily and need precise, repeatable guidance for each process. The Table of Contents below mirrors the structure of the F&O module and can be used either as a sequential onboarding path for new users or as a reference manual for specific tasks."})]})}function h(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var a=t(96540);let i={},o=a.createContext(i);function s(e){let n=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:n},e.children)}}}]);